/**
 * A pre-optimised landing image (R5b): AVIF first, WebP second, one `<img>`.
 *
 * The files live in `public/images/accueil/` as `<name>-<width>.avif|webp`,
 * generated by `scripts/landing-images.sh` (CLAUDE.md §13.1 nº 26). Never
 * `next/image`: the files are already resized, re-encoded and stripped, and
 * the optimiser would re-encode them at request time for nothing.
 *
 * `color` is the image's average colour, painted while the file loads, so a
 * slow network shows a matching block instead of a blank hole.
 */

const BASE = '/images/accueil';

export function srcSet(name: string, widths: readonly number[], ext: 'avif' | 'webp'): string {
  return widths.map((w) => `${BASE}/${name}-${w}.${ext} ${w}w`).join(', ');
}

export function imageUrl(name: string, width: number, ext: 'avif' | 'webp'): string {
  return `${BASE}/${name}-${width}.${ext}`;
}

export function LandingPicture({
  name,
  widths,
  width,
  height,
  sizes,
  color,
  className = '',
}: {
  name: string;
  widths: readonly number[];
  /** Intrinsic size of the fallback file (the largest width): reserves the box, no layout shift. */
  width: number;
  height: number;
  sizes: string;
  color: string;
  className?: string;
}) {
  const fallback = widths[widths.length - 1];
  return (
    <picture>
      <source type="image/avif" srcSet={srcSet(name, widths, 'avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet(name, widths, 'webp')} sizes={sizes} />
      <img
        src={imageUrl(name, fallback, 'webp')}
        alt=""
        width={width}
        height={height}
        loading="lazy"
        decoding="async"
        style={{ backgroundColor: color }}
        className={className}
      />
    </picture>
  );
}
